PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL, username_norm TEXT NOT NULL UNIQUE, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, backup_salt TEXT NOT NULL, created_at INTEGER NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, token_ver INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS backups (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, updated_at INTEGER NOT NULL, size_bytes INTEGER NOT NULL);
